on conflict (pays, etablissement, (coalesce(cursus, ''))) do update
  set filiere = coalesce(carmine_universites.filiere, excluded.filiere),
      domaine = coalesce(carmine_universites.domaine, excluded.domaine);

update carmine_universites set domaine = 'cam.ac.uk' where etablissement = 'University of Cambridge' and domaine is null;
update carmine_universites set domaine = 'warwick.ac.uk' where etablissement = 'University of Warwick' and domaine is null;
update carmine_universites set domaine = 'ucl.ac.uk' where etablissement = 'University College London' and domaine is null;
update carmine_universites set domaine = 'kcl.ac.uk' where etablissement = 'King''s College London' and domaine is null;
update carmine_universites set domaine = 'epfl.ch' where etablissement = 'EPFL' and domaine is null;
update carmine_universites set domaine = 'unibocconi.eu' where etablissement = 'Università Bocconi' and domaine is null;
update carmine_universites set domaine = 'stanislas.fr' where etablissement = 'Lycée Stanislas' and domaine is null;
update carmine_universites set domaine = 'bginette.com' where etablissement = 'Lycée Sainte-Geneviève' and domaine is null;
